import csv
import io


def inspect_csv(csv_text):
    if not csv_text or not csv_text.strip():
        return None
    reader = csv.reader(io.StringIO(csv_text))
    rows = list(reader)
    if not rows:
        return None
    columns = rows[0]
    row_count = len(rows) - 1
    return {'columns': columns, 'row_count': row_count}

def probability_of_event(outcomes, event):
    if not outcomes:
        return 0.0
    favourable = len(event)
    total = len(outcomes)
    return round(favourable / total, 4)

def handle_missing_values(values):
    if not values:
        return []
    present = [value for value in values if value is not None]
    if not present:
        return [0 for _ in values]
    mean = sum(present) / len(present)
    return [
        round(mean, 4) if value is None else value
        for value in values
    ]

def mean_squared_error(actual, predicted):
    if not actual or not predicted or len(actual) != len(predicted):
        return None
    total = 0.0
    for a, p in zip(actual, predicted):
        difference = a - p
        total += difference * difference
    return round(total / len(actual), 4)

def confusion_matrix(actual, predicted):
    if not actual or not predicted or len(actual) != len(predicted):
        return None
    true_positive = false_positive = true_negative = false_negative = 0
    for a, p in zip(actual, predicted):
        if a == 1 and p == 1:
            true_positive += 1
        elif a == 0 and p == 1:
            false_positive += 1
        elif a == 0 and p == 0:
            true_negative += 1
        elif a == 1 and p == 0:
            false_negative += 1
    return {
        'true_positive': true_positive,
        'false_positive': false_positive,
        'true_negative': true_negative,
        'false_negative': false_negative,
    }

